-- Delta posta-romana.ro (live) + OSM. Idempotent.
-- Comune: INSERT/UPDATE. Orase: UPDATE pe loc + INSERT + DELETE doar pt randuri nefolosite.
BEGIN;
SELECT setval('res_zip_id_seq', (SELECT MAX(id) FROM res_zip));

